}, state);   // a missing overload is a compile error

struct ConnectionState {                      // closed by convention
    virtual ~ConnectionState() = default;
    virtual void accept(Visitor&) const = 0;   // exhaustive consumer
protected:
    ConnectionState() = default;               // variants only
};
struct Connected final : ConnectionState {     // final: no illegal shapes
    std::string session_id;
    void accept(Visitor& v) const override { v.visit(*this); }
};
